#include<bits/stdc++.h>
#define int long long
using namespace std;
int mod=1e9+7;
int f(int x,int y){
	int sum=1;
	for(int i=y;i<=x;i++){
		sum=(sum*i)%mod;
	}
	return sum;
}
signed main() {
	freopen("robot.in","r",stdin);
	freopen("robot.out","w",stdout);
	int n,m;
	cin>>n>>m;
	cout<<f(n+m-2,m)/f(n-1,1);
	return 0;
}
